    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "壓縮會重新編碼視頻，可能會降低品質。如果某種格式無法保留音訊、字幕或資料軌道，處理將停止，而不是靜默刪除。您的原始影片不會被更改。",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "此瀏覽器無法將結果儲存為串流，因此將暫時使用裝置記憶體。過大的影片可能會超出瀏覽器或裝置的處理能力。",
