    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG,支援 PNG、WebP、HEIC/HEIF、AVIF、BMP、GIF/APNG、SVG 或 ICO 格式。動畫檔案匯出第一幀。元資料不會被複製。",
    "Transparent areas become white. Animated images use only their first frame.": "透明區域變為白色。動畫影像僅使用第一格。",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "支援 JPG、PNG、WebP、HEIC/HEIF、AVIF、BMP、GIF/APNG、SVG 和 ICO 格式。動畫檔案僅匯出第一幀。輸出最高可達 4000 萬像素。",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "在您的裝置上將常見影像格式轉換為 JPG、PNG 或 WebP 格式。最多可處理 20 個檔案。",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "最多可新增 20 張影像。檔案大小無限制；每張影像 2 千萬像素。批次處理取決於您的裝置記憶體。",
    "Images converted. Animated files become a still frame; metadata is not copied.": "影像已轉換。動畫檔案將轉換為靜態影格；元資料不會被複製。",
    "Some files were skipped. Use a supported image format within the on-page limits.": "部分檔案已被跳過。請使用頁面限制內支援的圖像格式。",
    "This image could not be decoded by your browser. Try another file or browser.": "您的瀏覽器無法解碼此圖像。請嘗試其他文件或瀏覽器。",
    "Choose a supported image format.": "請選擇支援的影像格式。",
    "The browser does not support the selected output format.": "瀏覽器不支援所選的輸出格式。",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "最多 20 張圖片 · 每張圖片 2000 萬像素 · 無固定檔案大小限制。批次處理取決於您的裝置記憶體。",
    "Choose up to 20 images.": "最多選擇 20 張影像。",
    "AVIF and some HEIC files may depend on browser support.": "AVIF 和部分 HEIC 檔案可能取決於瀏覽器支援。",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "AVIF 和部分 HEIC 輸入取決於瀏覽器支援。動畫 GIF、APNG 和 WebP 檔案將轉換為靜態影像。 SVG 是柵格化影像，而不是轉換為可編輯的向量圖。元資料不會被複製。",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "多頁 TIFF 檔案僅使用第一頁。某些 TIFF 壓縮格式可能無法解碼。",
    "Choose a DOCX, XLSX or PPTX file": "選擇 DOCX、XLSX 或 PPTX 文件",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "檔案保留在您的裝置上。限制：輸入檔案大小不超過 100 MB，擴充資料不超過 200 MB，以及最多 5,000 個檔案包元件。",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "此操作會安全地重新壓縮 Office 包，而不會重寫其內容。嵌入的圖片不會被重新壓縮，因此結果檔案大小可能不會減少。不支援已簽署、已加密、啟用巨集以及舊版 Office 檔案。請保留您的原始文件。",
    "Try to reduce file size": "嘗試減少檔案大小",
    "Processing runs locally in this browser. No upload.": "處理過程在此瀏覽器中本地運行。無需上傳。",
    "Recompressing the Office package on your device…": "正在重新壓縮裝置上的 Office 套件…",
    "This package is already compact. No smaller download was created.": "此套件已壓縮完畢。未建立更小的下載檔案。",
    "A smaller copy is ready. Compare it and keep your original.": "已產生更小的副本。請進行比較並保留原始文件。",
    "The file could not be safely recompressed. Your original has not changed.": "無法安全地重新壓縮檔案。您的原始文件未更改。",
    "Processing canceled. Your original file is unchanged.": "處理已取消。您的原始文件未更改。",
    "Choose a modern DOCX, XLSX or PPTX file.": "請選擇現代的 DOCX、XLSX 或 PPTX 檔案。",
    "This file is larger than the 100 MB local processing limit.": "此檔案大於 100 MB 的本機處理限制。",
    "The expanded package exceeds the 200 MB local processing limit.": "解壓縮後的套件超過了 200 MB 的本地處理限制。",
    "Encrypted Office packages are not supported.": "不支援加密的 Office 套件。",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "不支援已簽署或啟用巨集的 Office 文件，以避免簽章或巨集失效。",
    "The selected file is not a valid modern Office document of that type.": "所選檔案不是該類型的有效現代 Office 文件。",
