    "This file or codec could not be processed. Try another supported format.": "無法處理此檔案或編解碼器。請嘗試其他支援的格式。",
    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "對於較長或高解析度的媒體文件，建議使用桌上型電腦或筆記型電腦。請保持此標籤頁開啟；速度、記憶體和電池續航時間取決於您的裝置。",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "重新編碼可能會降低音質或產生更大的檔案。您的原始文件保持不變。",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "首次使用會下載約 58 MB 的型號和本地引擎資訊。您的錄音尚未上傳；如果清除瀏覽器緩存，瀏覽器可能會重新下載這些檔案。",
