    "Strong compression (pages become images)": "強力壓縮（頁面會轉成影像）",
    "PDFs are processed on this device, never uploaded. Compression has no fixed file-size cap; available memory and browser support are the practical limits.": "PDF 檔案在此裝置上處理，不會上傳。壓縮檔案大小沒有固定上限；可用記憶體和瀏覽器支援是實際的限制。",
    "Best first try: rewrites and recompresses PDF structure without turning pages into images. Text and layout usually remain, but not every special feature is guaranteed; editing a signed PDF may invalidate its signature. It may not get smaller.": "建議先試此選項：重新寫入並壓縮 PDF 結構，不會將頁面轉成影像。通常保留文字與版面，但不保證所有特殊功能；編輯已簽署的 PDF 可能使簽章失效，檔案也可能不會變小。",
    "Review this before continuing": "繼續前請先確認",
    "Every page is rebuilt as an image. Text will no longer be searchable or selectable; links, forms, annotations, accessibility structure and signatures will not be preserved. Small text or fine details may look worse, and the file can even grow. Always compare the result and keep your original.": "每頁都會重建為影像。文字將無法搜尋或選取；連結、表單、註解、無障礙結構與簽章不會保留。小字或細節可能變差，檔案甚至可能變大。請務必比較結果並保留原始檔案。",
    "I understand these trade-offs and will keep the original.": "我了解這些取捨，並會保留原始檔案。",
    "Image quality": "影像品質",
    "Balanced · clearer text": "平衡・文字較清晰",
    "Smaller file · lower detail": "檔案較小・細節較少",
    "Cancel": "取消",
    "PDF compression canceled. No new file was saved.": "PDF 壓縮已取消。未儲存新文件。",
    "Optimizing PDF structure on your device…": "正在優化裝置上的 PDF 結構…",
    "Rendering page {current} of {total} on your device…": "正在渲染設備上的 {current} 頁（共 {total} 頁）…",
    "Creating the compressed PDF on your device…": "正在建立裝置上的壓縮 PDF…",
    "This method did not make the PDF smaller. The original is unchanged. Try the other mode.": "此方法並未縮小 PDF 檔案大小。原始文件未更改。請嘗試其他模式。",
    "PDF optimization made the file {size} smaller. Compare it before using it. Your original is unchanged.": "PDF 優化後檔案 {size} 已縮小。使用前請進行比較。原始文件未更改。",
    "Image compression made the file {size} smaller. Inspect readability; the original is unchanged.": "影像壓縮後檔案 {size} 已縮小。請檢查可讀性；原始文件未更改。",
    "Choose a video": "選擇一個視頻",
    "The video is processed on your device and is never uploaded. There is no fixed file-size cap; available memory, storage and browser codecs set practical limits.": "影片在您的裝置上處理，不會上傳。檔案大小沒有固定限制；可用記憶體、儲存空間和瀏覽器編解碼器決定了實際大小。",
    "MP4 · broadly compatible": "MP4 · 廣泛相容",
    "WebM · open format": "WebM · 開放式格式",
    "Quality": "品質",
    "Higher quality · larger file": "更高品質 · 文件較大",
    "Balanced": "平衡",
    "Smaller file · more quality loss": "更小文件 · 質量損失更大",
    "Maximum resolution": "最高解析度",
    "Keep original resolution": "保持原始分辨率",
    "Up to 1080p": "最高支援 1080p",
    "Up to 720p": "最高支援 720p",
    "Before you start": "開始之前",
    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "壓縮會重新編碼視頻，可能會降低品質。如果某種格式無法保留音訊、字幕或資料軌道，處理將停止，而不是靜默刪除。您的原始影片不會被更改。",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "此瀏覽器無法將結果儲存為串流，因此將暫時使用裝置記憶體。過大的影片可能會超出瀏覽器或裝置的處理能力。",
    "Compress video": "壓縮視頻",
    "Video compression progress": "視訊壓縮進度",
    "No upload. Keep this tab open while your device works.": "暫無上傳。請在設備工作期間保持此標籤頁開啟。",
