    "Compressed video is {size} smaller. Review it before sharing; your original is unchanged.": "壓縮後的視訊體積縮小了 {size} 倍。分享前請檢查；您的原始影片未發生變化。",
    "This video could not be made smaller. No copy was saved; your original is unchanged. Try a lower quality or resolution.": "此影片無法進一步壓縮。未儲存任何副本；您的原始影片未變更。請嘗試降低視訊品質或解析度。",
    "Video compression canceled. No compressed copy was kept.": "視訊壓縮已取消。未保存任何壓縮副本。",
    "Save was canceled. Your original video is unchanged.": "已儲存取消。您的原始影片未發生變化。",
    "This video has an audio, subtitle or data track that the selected format cannot keep. No output was saved.": "此影片包含所選格式無法保留的音訊、字幕或資料軌。未保存輸出。",
