    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "首次使用會下載約 58 MB 的型號和本地引擎資訊。您的錄音尚未上傳；如果清除瀏覽器緩存，瀏覽器可能會重新下載這些檔案。",
