    "Check the selected file and settings, then try again.": "請檢查所選檔案和設置，然後再試一次。",
    "Up to 200 files; 100 MB total or expanded. ZIP64 and password-protected files are not supported. Large archives use device memory; a computer is recommended.": "支援最多 200 個檔案；總大小或擴充大小不超過 100 MB。不支援 ZIP64 和密碼保護的檔案。大型壓縮包會佔用設備記憶體；建議使用電腦。",
    "Convert / trim": "轉換/裁剪",
    "Estimate only, not a loan offer. Fees, taxes, insurance and lender terms are not included.": "僅供參考，非貸款報價。費用、稅金、保險和貸款條款均不包含在內。",
    "Illustration only; actual returns vary and are not guaranteed. Taxes, inflation and fees are excluded.": "僅供參考；實際收益可能有所不同，且不保證。稅金、通貨膨脹和手續費均不包含在內。",
