    "Role · Company · dates&#10;What you did and achieved": "角色 · 公司 · 日期 | 您的工作內容和成就",
    "Choose a portrait image.": "選擇一張人像圖片。",
    "Remove the background from a portrait and save a transparent PNG on your device.": "移除人像圖片的背景，並將透明 PNG 圖片儲存到您的裝置。",
