    "Visual edits flatten modified pages; searchable text on them is lost. Limit: 50 MB, 100 pages, 40 MP. A computer is recommended.": "視覺編輯會將修改過的頁面合併；頁面上的可搜尋文字將會遺失。限制：50 MB，100 頁，4000 萬像素。建議使用電腦。",
