                "保持每個結果的寬度為四位，包括零。",
                "用空格分隔組以便檢查結果；僅當目標需要一個連續字串時才刪除空格。",
                "如果輸入包含前綴（例如 0x），請在將數字輸入到僅接受數值的轉換器之前，先移除該前綴。"
